('2026-09-28','Squat hypertrophy + cleans','Symmetry CrossFit','[{"name":"Warmup and tech","text":"Overhead positioning. 3 to 4 rounds: 3 to 5 light snatch, 3 to 5 OHS, 10 banded good mornings, 10 to 20 banded reverse squats"},{"name":"Squat hypertrophy, 14 min","text":"EMOM x7. First 3 sets: 8 overhead squats. Last 4 sets: 8 front squats"},{"name":"Conditioning","text":"3 rounds for time: 10 cleans 135/95 (Rx+ 185/125), 15 burpees over the bar"}]'::jsonb,'[{"id":"ohs","n":"Overhead squat","sch":"3 x 8","b":"squat","f":0.372,"why":"62% of est. OHS max (60% of squat)"},{"id":"fs","n":"Front squat","sch":"4 x 8","b":"squat","f":0.5780000000000001,"why":"68% of est. front squat (85% of squat)"},{"id":"clc","n":"Cleans in the WOD","sch":"30 reps","rx":[135,185],"b":"clean","why":"135 Rx. Go 185 once your clean is 265+"}]'::jsonb,'Time','time',null,null),
