('2026-10-01','Press hypertrophy','Symmetry CrossFit','[{"name":"Warmup","text":"Shoulder mobility and stabilizers. 3 to 4 rounds: 1 wall walk + :10 hold, 10 DB hanging knee raises, 10 to 15 single leg calf raises, 15 to 25 tib raises"},{"name":"Press hypertrophy, 12 min","text":"Every 2:30, 10 to 15 reps: dual DB strict press AMRAP, then push press AMRAP"},{"name":"Conditioning","text":"4 sets for time: row or ski 300/250 or bike 18/12 cal, 10 barbell rows 95/65 (Rx+ 135/85)"}]'::jsonb,'[{"id":"dbp","n":"Dual DB press (each hand)","sch":"AMRAP 10 to 15","b":"bench","f":0.2,"why":"About 20% of your bench per dumbbell"},{"id":"bbr","n":"Barbell row","sch":"40 reps","rx":[95,135],"b":"bench","f2":0.5,"why":"Rx+ 135 if your bench is 270+"}]'::jsonb,'Time','time',null,null),
